const form = $('Storeleads Launch').first().json;
const CMAP = {'United States':'US','United Kingdom':'GB','Canada':'CA','Australia':'AU','Ireland':'IE','Israel':'IL','Germany':'DE','France':'FR','Netherlands':'NL','usa':'US','us':'US','uk':'GB','england':'GB'};
const asArr=(v)=>{ if(v===undefined||v===null||v==='')return[]; if(Array.isArray(v))return v.map(x=>String(x).trim()).filter(Boolean); return String(v).split(',').map(s=>s.trim()).filter(Boolean); };
const toCode=(x)=>{ const s=String(x).trim(); if(CMAP[s])return CMAP[s]; if(CMAP[s.toLowerCase()])return CMAP[s.toLowerCase()]; if(/^[A-Za-z]{2}$/.test(s))return s.toUpperCase(); return ''; };
const ccList = Array.from(new Set(asArr(form['Country']).map(toCode).filter(Boolean)));
const ALLOWED = ['shopify','woocommerce','bigcommerce','wix','squarespace','magento'];
let selP = asArr(form['Platforms (tick any; none = all platforms)']).map(s=>String(s).toLowerCase()).filter(s=>ALLOWED.includes(s));
const planTicked = asArr(form['Plan']).includes('Shopify Plus');
if (planTicked) selP = ['shopify'];
const providers = selP.length ? Array.from(new Set(selP)) : ['all'];
const maxCompanies = Math.max(1, parseInt(form['Max companies'], 10) || 500);
const baseFilters = { 'f:state': 'Active' };
if (planTicked) baseFilters['f:plan'] = 'Shopify Plus';
const envelope=(ticked, ORDER, MAP)=>{ const s=ticked.filter(b=>MAP[b]); if(!s.length) return [null,null]; const idxs=s.map(b=>ORDER.indexOf(b)).filter(i=>i>=0).sort((a,b)=>a-b); return [MAP[ORDER[idxs[0]]][0], MAP[ORDER[idxs[idxs.length-1]]][1]]; };
const REV_ORDER=['Under $10k','$10k-50k','$50k-100k','$100k-500k','$500k-1M','$1M+'];
const REV={'Under $10k':[null,1000000],'$10k-50k':[1000000,5000000],'$50k-100k':[5000000,10000000],'$100k-500k':[10000000,50000000],'$500k-1M':[50000000,100000000],'$1M+':[100000000,null]};
const rev=envelope(asArr(form['Monthly revenue']),REV_ORDER,REV);
if(rev[0]!=null)baseFilters['f:ermin']=String(rev[0]); if(rev[1]!=null)baseFilters['f:ermax']=String(rev[1]);
const EMP_ORDER=['1-10','11-50','51-200','200+'];
const EMP={'1-10':[1,10],'11-50':[11,50],'51-200':[51,200],'200+':[200,null]};
const emp=envelope(asArr(form['Employees']),EMP_ORDER,EMP);
if(emp[0]!=null)baseFilters['f:empcmin']=String(emp[0]); if(emp[1]!=null)baseFilters['f:empcmax']=String(emp[1]);
const PC_ORDER=['1-50','51-500','500+'];
const PC={'1-50':[1,50],'51-500':[51,500],'500+':[500,null]};
const pc=envelope(asArr(form['Product count']),PC_ORDER,PC);
if(pc[0]!=null)baseFilters['f:pcmin']=String(pc[0]); if(pc[1]!=null)baseFilters['f:pcmax']=String(pc[1]);
const iso=(d)=>d.toISOString().slice(0,19)+'Z';
const now=new Date();
const yearsAgo=(y)=>{ const d=new Date(now.getTime()); d.setUTCFullYear(d.getUTCFullYear()-y); return d; };
const AGE_ORDER=['Under 1 year','1-3 years','3+ years'];
const AGE={'Under 1 year':[0,1],'1-3 years':[1,3],'3+ years':[3,null]};
const ageTicked=asArr(form['Store age']).filter(b=>AGE[b]);
if(ageTicked.length){ const aidx=ageTicked.map(b=>AGE_ORDER.indexOf(b)).filter(i=>i>=0).sort((a,b)=>a-b); const minAge=AGE[AGE_ORDER[aidx[0]]][0]; const maxAge=AGE[AGE_ORDER[aidx[aidx.length-1]]][1]; if(maxAge!=null)baseFilters['f:cratmin']=iso(yearsAgo(maxAge)); if(minAge>0)baseFilters['f:cratmax']=iso(yearsAgo(minAge)); }
const minVisits = parseInt(form['Min monthly visits'], 10);
if (Number.isFinite(minVisits) && minVisits > 0) baseFilters['f:evmin'] = String(minVisits);
const catList = asArr(form['Category']);
if (catList.length) { baseFilters['f:cat'] = catList.join(','); baseFilters['f:cat:op'] = 'or'; }
const techList = asArr(form['Technologies']);
if (techList.length) { baseFilters['f:tech'] = techList.join(','); baseFilters['f:tech:op'] = 'and'; }
const appRaw = form['Must-have app IDs (comma-separated, platform.token format, e.g. shopify.klaviyo-email-marketing)'];
const appIds = (appRaw==null?'':String(appRaw)).split(',').map(s=>s.trim()).filter(Boolean);
if (appIds.length) { baseFilters['f:an']=appIds.join(','); baseFilters['f:an:op']='and'; }
const fields = 'name,tld1,merchant_name,title,description,categories,country_code,city,administrative_area_level_1,estimated_sales,employee_count,rank,platform,state,plan,created_at,product_count,monthly_app_spend,apps,technologies,trustpilot,last_platform,last_platform_change_at,features,contact_info';
const cList = ccList.length ? ccList : [null];
const out=[];
for(const p of providers){ for(const cc of cList){ const f = Object.assign({}, baseFilters); if(cc) f['f:cc']=cc; const countQuery = Object.assign({}, f, { page_size: 1, fields: 'tld1' }); const pullQuery = Object.assign({}, f, { page_size: 50, sort: 'rank', fields }); out.push({ json: { _provider: p, _country: cc||'ALL', countryCode: cc||'', _ccList: ccList, countQuery, pullQuery, maxCompanies, providerCount: providers.length, countryCount: cList.length } }); } }
return out;

const g = $('Launch Guard').first().json;
const t = (n) => ({ name: n, type: 'singleLineText' });
const num = (n, p) => ({ name: n, type: 'number', options: { precision: (p===undefined?0:p) } });
const sel = (n, ch) => ({ name: n, type: 'singleSelect', options: { choices: ch } });
const MV=[{name:'ok',color:'greenBright'},{name:'catch_all',color:'yellowBright'},{name:'invalid',color:'redBright'},{name:'disposable',color:'orangeLight2'},{name:'unknown',color:'grayBright'},{name:'error',color:'orangeBright'},{name:'skipped',color:'grayLight2'}];
const BB=[{name:'verifying',color:'blueBright'},{name:'deliverable',color:'greenBright'},{name:'undeliverable',color:'redBright'},{name:'risky',color:'yellowBright'},{name:'unknown',color:'grayBright'},{name:'error',color:'orangeBright'},{name:'skipped',color:'grayLight2'}];
const STc=[{name:'done',color:'greenBright'},{name:'verifying',color:'blueBright'},{name:'no_email_found',color:'redBright'},{name:'error',color:'orangeBright'}];
const EMP=[{name:'1-10'},{name:'11-50'},{name:'51-200'},{name:'201-500'},{name:'501-1000'},{name:'1001-5000'},{name:'5001-10000'},{name:'10001+'}];
const fields = [
  t('Domain'), t('Company'), t('public_emails_clean'), t('Industry Groups'), sel('Employees', EMP),
  t('City'), t('State'), t('Country'), t('Description'), t('Plan'),
  num('Revenue Est Monthly',0), num('Store Age Years',1), num('Product Count',0), num('App Spend Mo',0),
  t('Key Apps'), t('Tech Stack'), num('Trustpilot Rating',1), num('Trustpilot Reviews',0),
  t('Migrated From'), t('Social Followers'), t('Features'),
  t('segment'), t('Contact Source'), t('Tag'),
  sel('MV P0', MV), sel('BB', BB), t('Final Email'), sel('Status', STc)
];
// `Build Date` is a computed field, never a writable column, so nothing can overwrite a
// row's first-build date. It lives in `formulaFields` because Airtable rejects computed
// fields inside a create-table call; `Table Router` routes these to be added after the
// table exists. `Run ID` is retired: it recorded the last run, not the first build.
// `Tag` is the Operator's optional launch label, written onto every row of the build.
// 2026-08-12 Operator ruling: company_clean retired (the cleaned name lives in Company itself);
// 'Contact Source' replaces 'Source' for record provenance. 'Email Source' (waterfall tier) is
// owned by the verification lane, which creates it on first touch.
const formulaFields = [{ name: 'Build Date', type: 'formula', options: { formula: 'CREATED_TIME()' } }];
const desiredName = (g.buildName || 'List') + ' - Domains';
return [{ json: { mode: g.mode, existingTableId: g.existingTableId, buildNameIgnored: !!g.buildNameIgnored, desiredName, fields, formulaFields } }];

const j = $input.first().json || {};
if (j && j.mode === 'append') {
  if (!j.tableId) { throw new Error('Table resolution returned no table id: ' + JSON.stringify(j).slice(0,400)); }
  return [{ json: { tableId: j.tableId, tableName: j.tableName, mode: 'append', fieldsCreated: j.fieldsCreated || [], buildNameIgnored: !!j.buildNameIgnored, createdFieldError: j.createdFieldError || '' } }];
}
const ct = $('Created Table Guard').first().json || {};
return [{ json: { tableId: ct.tableId, tableName: ct.tableName, mode: 'create', fieldsCreated: (ct.fieldNames || []), buildNameIgnored: false, createdFieldError: '' } }];

const form=$('Storeleads Launch').first().json;
const started=form.submittedAt || $('Config').first().json.startedAt;
const sd=$getWorkflowStaticData('global');
const t=(sd.slBatchState&&sd.slBatchState.totals)||{pulled:0,inserted:0,withEmails:0,skipped:0};
const stores=t.pulled;
const total=t.inserted;
const hasPublic=t.withEmails;
const skipped=Number(t.skipped)||0;
const noPublic=Math.max(0,total-hasPublic);
let clientRec=[];
try{ const rc=$('Resolve Client').first().json; if(rc&&rc.id) clientRec=[rc.id]; }catch(e){}
const g=$('Companies Table Guard').first().json||{};
const tableName=g.tableName||'';
const tableId=g.tableId||'';
const modeTxt=(g.mode==='append')?'appended to an existing table':'created a new table';
const fc=(g.fieldsCreated&&g.fieldsCreated.length)?g.fieldsCreated.join(', '):'none';
const tag=((form['Tag']||'')+'').trim();
let dur=0; try{ if(started) dur=Math.max(0,Math.round(($now.toMillis()-new Date(started).getTime())/1000)); }catch(e){}
const trig='form';
const errors=g.createdFieldError?1:0;
const fmt=v=>Number(v||0).toLocaleString('en-US');
const parts=[];
parts.push('**'+fmt(stores)+' stores pulled, '+fmt(total)+' upserted**');
parts.push('**Tag:** '+(tag||'none'));
parts.push('**Results**\n- **Upserted to Domains table:** '+fmt(total)+'\n- **With public emails:** '+fmt(hasPublic)+'\n- **Without public emails:** '+fmt(noPublic)+'\n- **Skipped (empty domain):** '+fmt(skipped));
parts.push('**Table:** '+modeTxt+', '+tableName+' ('+tableId+')\n**Fields created:** '+fc);
const warns=[];
if(g.createdFieldError){ warns.push('- '+g.createdFieldError); }
if(g.buildNameIgnored){ warns.push('- Build name ignored: an Existing Table ID was supplied.'); }
if(warns.length){ parts.push('**Warnings ('+warns.length+')**\n'+warns.join('\n')); }
parts.push('**Source:** Storeleads ('+trig+'-launched)');
const log={
  'Automation':'Storeleads Domains -> Clayroots',
  'Status': errors?'Succeeded with errors':'Succeeded',
  'Trigger': trig,
  'Errors': errors,
  'Run at': $now.toISO(),
  'Target': tableName+' ('+tableId+')',
  'Records In': stores,
  'Records Out': total,
  'Duration s': dur,
  'Description': parts.join('\n\n'),
  'Execution Link':'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id,
  'Execution ID': String($execution.id)
};
if(clientRec.length){ log['Client']=clientRec; }
return [{ json: log }];

const qs = $('Build SL Query').all().map(i => ({ provider: i.json._provider, pullQuery: i.json.pullQuery }));
const cap = Math.max(1, Number($('Build SL Query').first().json.maxCompanies) || 500);
const sd = $getWorkflowStaticData('global');
sd.slBatchState = { cap, qIndex: 0, cursor: '', batchNum: 0, retried: false, remaining: cap, totals: { pulled: 0, inserted: 0, withEmails: 0, skipped: 0 } };
return [{ json: { action: 'continue', qIndex: 0, cursor: '', remaining: cap, queries: qs } }];

const res = $input.first().json;
const sd = $getWorkflowStaticData('global');
const st = sd.slBatchState;
if (!st) throw new Error('Loop state missing: Init Loop State did not run');
const queries = $('Init Loop State').first().json.queries || [];
st.batchNum = (st.batchNum || 0) + 1;
if (st.batchNum > 500) throw new Error('Storeleads batch loop hit the hard cap of 500 batches. Totals so far: pulled ' + st.totals.pulled + ', inserted ' + st.totals.inserted + '. Last cursor: "' + st.cursor + '" (query ' + (st.qIndex + 1) + '/' + queries.length + ').');
if (res.errorPages && res.errorPages > 0) {
  if (st.retried) {
    throw new Error('Storeleads returned error pages twice for cursor "' + st.cursor + '" (provider ' + ((queries[st.qIndex] || {}).provider || '?') + ', query ' + (st.qIndex + 1) + '/' + queries.length + '). Totals so far: pulled ' + st.totals.pulled + ', inserted ' + st.totals.inserted + ', withEmails ' + st.totals.withEmails + '.');
  }
  st.retried = true;
  return [{ json: { action: 'retry', qIndex: st.qIndex, cursor: st.cursor, remaining: st.remaining } }];
}
st.retried = false;
st.totals.pulled += Number(res.pulled) || 0;
st.totals.inserted += Number(res.inserted) || 0;
st.totals.withEmails += Number(res.withEmails) || 0;
st.totals.skipped = (Number(st.totals.skipped) || 0) + (Number(res.skipped) || 0);
st.remaining = Math.max(0, st.cap - st.totals.inserted);
if (res.has_next_page && st.remaining > 0 && res.next_cursor) {
  st.cursor = String(res.next_cursor);
  return [{ json: { action: 'continue', qIndex: st.qIndex, cursor: st.cursor, remaining: st.remaining } }];
}
st.qIndex += 1;
st.cursor = '';
if (st.qIndex < queries.length && st.remaining > 0) {
  return [{ json: { action: 'continue', qIndex: st.qIndex, cursor: '', remaining: st.remaining } }];
}
return [{ json: { action: 'done', pulled: st.totals.pulled, inserted: st.totals.inserted, withEmails: st.totals.withEmails, skipped: st.totals.skipped } }];

const form = $('Storeleads Launch').first().json;
const build = ((form['Build name'] || '') + '').trim();
const tid = ((form['Existing Table ID'] || '') + '').trim();
if (!build && !tid) { throw new Error('Provide a Build name (to create a new table) or an Existing Table ID (to append to one). Nothing was pulled.'); }
if (tid && !/^tbl[A-Za-z0-9]{14}$/.test(tid)) { throw new Error('Existing Table ID "' + tid + '" is not a valid Airtable table id (expected tbl followed by 14 characters). Nothing was pulled.'); }
return [{ json: { buildName: build, existingTableId: tid, mode: tid ? 'append' : 'create', buildNameIgnored: !!(tid && build) } }];

// ---------------------------------------------------------------------------
// The contract arrives CORRECT from `Companies Schema`: `Build Date` is declared in
// `formulaFields` as a CREATED_TIME() formula, and `Run ID` is gone. This node does
// not rewrite the contract; it only routes and guards it.
//
// `Build Date` must stay a formula. It is a computed field in all 23 ClayRoots tables:
// writing it returns 422, and declaring it as `type: date` anywhere makes every append
// fail the type-clash guard below. That is the bug that re-dated 731 rows in Piper.
//
// The COMPUTED branch is the guard, not boilerplate. Absent from the target table ->
// pushed to `missing` so it gets created afterwards. Present as a formula -> skipped.
// Present as any other type -> throw, because that table has not been converted yet.
// ---------------------------------------------------------------------------
const spec = $('Companies Schema').first().json;
const baseId = (($('Storeleads Launch').first().json['Clayroots Base ID'])||'').trim();
const resp = $('AT List Tables').first().json || {};
const tables = Array.isArray(resp.tables) ? resp.tables : null;
if (!tables) { throw new Error('Could not read the table list for base ' + baseId + ': ' + JSON.stringify(resp).slice(0,400) + '. Nothing was written.'); }
const norm = (s) => String(s == null ? '' : s).trim().toLowerCase();
const plain = spec.fields || [];
const formulas = spec.formulaFields || [];
if (spec.mode !== 'append') {
  const taken = new Set(tables.map(t => String(t.name)));
  let name = spec.desiredName; let n = 1;
  while (taken.has(name)) { n++; name = spec.desiredName + ' (' + n + ')'; }
  // Airtable refuses a computed field inside a create-table call, so the formula
  // fields ride out as `missing` and are added after the table exists.
  return [{ json: { mode: 'create', createName: name, fields: plain, missing: formulas, missingNames: formulas.map(f => f.name), buildNameIgnored: false } }];
}
const target = tables.find(t => t.id === spec.existingTableId);
if (!target) { throw new Error('Table ' + spec.existingTableId + ' does not exist in base ' + baseId + '. Tables there: ' + tables.map(t => t.name).join(', ') + '. Nothing was written.'); }
if (/contacts/i.test(String(target.name || ''))) { throw new Error("Refusing to write domains into '" + target.name + "' - that table is a contacts table. Nothing was written."); }
const targetFields = target.fields || [];
const existing = new Map(targetFields.map(f => [f.name, f]));
// Airtable field names are case-insensitive on creation, so a case variant of a computed
// field has to be recognised as present and type-checked, never pushed to `missing`.
const existingCI = new Map(targetFields.map(f => [norm(f.name), f]));
const COMPUTED = new Set(formulas.map(f => f.name));
const kind = (ty) => ty === 'number' ? 'number' : (ty === 'singleSelect' ? 'select' : (ty === 'date' ? 'date' : 'text'));
const okWith = { number: ['number'], text: ['singleLineText','multilineText','singleSelect'], select: ['singleSelect','singleLineText'], date: ['date','dateTime'] };
const contract = plain.concat(formulas);
const clashes = []; const missing = [];
for (const cf of contract) {
  if (COMPUTED.has(cf.name)) {
    const exc = existingCI.get(norm(cf.name));
    if (!exc) { missing.push(cf); continue; }
    if (exc.type !== 'formula') { throw new Error("Table '" + target.name + "' (" + target.id + ') still has a writable ' + cf.name + ' (type: ' + exc.type + '). Convert it to a CREATED_TIME() formula field before building. Nothing was written.'); }
    continue;
  }
  const ex = existing.get(cf.name);
  if (!ex) { missing.push(cf); continue; }
  if (!okWith[kind(cf.type)].includes(ex.type)) { clashes.push(cf.name + ' (type in table: ' + ex.type + ', type expected: ' + cf.type + ')'); }
}
if (clashes.length) { throw new Error("Type clash in table '" + target.name + "' (" + target.id + '): ' + clashes.join('; ') + '. Nothing was written.'); }
return [{ json: { mode: 'append', tableId: target.id, tableName: target.name, fields: contract, missing, missingNames: missing.map(f => f.name), buildNameIgnored: !!spec.buildNameIgnored } }];

const r = $('Table Router').first().json;
let rows = [];
try { rows = $('AT Read Domains').all().map(i => i.json || {}); } catch (e) { rows = []; }
const counts = new Map();
for (const it of rows) {
  const raw = (it.Domain !== undefined) ? it.Domain : ((it.fields || {}).Domain);
  const d = String(raw == null ? '' : raw).trim().toLowerCase();
  if (!d) continue;
  counts.set(d, (counts.get(d) || 0) + 1);
}
const dups = Array.from(counts.entries()).filter(e => e[1] > 1).map(e => e[0]);
if (dups.length) { throw new Error("Target table '" + r.tableName + "' has repeated Domain values (e.g. " + dups.slice(0,3).join(', ') + '), which means it is contact-shaped. Refusing to upsert on Domain. Nothing was written.'); }
return [{ json: Object.assign({}, r, { fieldsCreated: [], domainsChecked: counts.size }) }];

const r = $('Table Router').first().json;
const baseId = (($('Storeleads Launch').first().json['Clayroots Base ID'])||'').trim();
const resp = $('AT Verify Schema').first().json || {};
const tables = Array.isArray(resp.tables) ? resp.tables : null;
if (!tables) { throw new Error('Could not re-read the schema of base ' + baseId + ' after creating fields: ' + JSON.stringify(resp).slice(0,400) + '. Nothing was written.'); }
const target = tables.find(t => t.id === r.tableId);
if (!target) { throw new Error('Table ' + r.tableId + ' is no longer present in base ' + baseId + '. Nothing was written.'); }
const norm = (s) => String(s == null ? '' : s).trim().toLowerCase();
const targetFields = target.fields || [];
const have = new Set(targetFields.map(f => f.name));
// Computed fields are matched case-insensitively, exactly as the router matches them, so a
// table carrying a case variant is not reported as a field we failed to create.
const haveCI = new Set(targetFields.map(f => norm(f.name)));
const isComputed = (f) => !!f && f.type === 'formula';
const still = (r.fields || []).filter(f => isComputed(f) ? !haveCI.has(norm(f.name)) : !have.has(f.name)).map(f => f.name);
if (still.length) { throw new Error("Could not create these fields on '" + target.name + "' (" + target.id + '): ' + still.join(', ') + '. Nothing was written.'); }
const wanted = r.missingNames || [];
const created = wanted.filter(n => have.has(n) || haveCI.has(norm(n)));
return [{ json: { mode: 'append', tableId: target.id, tableName: target.name, fieldsCreated: created, buildNameIgnored: !!r.buildNameIgnored, createdFieldError: '' } }];

const j = $input.first().json || {};
const baseId = (($('Storeleads Launch').first().json['Clayroots Base ID'])||'').trim();
if (!j.id) { throw new Error('Airtable table creation failed in base ' + baseId + ': ' + JSON.stringify(j).slice(0,400)); }
return [{ json: { mode: 'create', tableId: j.id, tableName: j.name, fieldNames: (j.fields || []).map(f => f.name) } }];
